/**
 * Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty object. Note that you should only return the payload of the decoded thing.
 *
 * @param {string} token - The JWT token to decode.
 * @param {string} key - The key used in encoding.
 * @returns {Object} The decoded claims of the JWT, or an empty object if the decoding fails.
 */
function decodeJsonWebToken(token, key) {
  try {
    // jwt.verify decodes the token and verifies its signature and claims (like expiration).
    // It returns the decoded payload if verification is successful.
    // We explicitly specify the 'HS256' algorithm to ensure compliance with the docstring
    // and to prevent algorithm confusion attacks.
    const decoded = jwt.verify(token, key, { algorithms: ['HS256'] });
    return decoded;
  } catch (error) {
    // If jwt.verify throws an error (e.g., invalid signature, expired token, malformed token,
    // incorrect algorithm, or any other verification failure), we catch it and return
    // an empty object as specified in the docstring.
    return {};
  }
}
